import {AgentAuthorizationBanner} from '@github-ui/agent-authorization-dialog/banner'
import {
  mockAgentAuthState,
  needsAuthorizationFromTokenStatus,
  requestAuthorizationUrl,
} from '@github-ui/agent-authorization-dialog/mock-client'
import {useAgentAuthorizationStatuses} from '@github-ui/agent-authorization-dialog/statuses'
import type {AgentAuthorizationAgent} from '@github-ui/agent-authorization-dialog/types'
import {useCallback, useEffect, useState} from 'react'

import styles from './AgentAuthorizationBannerPartial.module.css'

const OPEN_EVENT = 'open-agent-authorization-banner'
const CLOSE_EVENT = 'close-agent-authorization-banner'

export type OpenAgentAuthorizationBannerEventDetail = {
  /** Stable agent slug, e.g. "anthropic-code-agent". */
  slug: string
  displayName: string
  avatarUrl?: string
  /** Server-precomputed status from the 5-part Rails token; bypasses mock fallback. */
  authorizationStatus?: 'authorized' | 'needs_authorization'
}

declare global {
  interface WindowEventMap {
    [OPEN_EVENT]: CustomEvent<OpenAgentAuthorizationBannerEventDetail>
    [CLOSE_EVENT]: CustomEvent<void>
  }
}

export type AgentAuthorizationBannerPartialProps = {
  /** Repository "owner/name" — required to call the real authorize endpoint. */
  nwo?: string
}

/**
 * React partial for `<copilot-mentions-hint>`: subscribes to window events to render
 * an inline banner when an unauthorized-agent mention is detected in a composer.
 */
export function AgentAuthorizationBannerPartial({nwo}: AgentAuthorizationBannerPartialProps = {}) {
  const [agent, setAgent] = useState<AgentAuthorizationAgent | null>(null)

  // Fetch the per-repo agents list to resolve `integrationId` from slug.
  const {data: agentAuthStatuses} = useAgentAuthorizationStatuses(nwo)

  useEffect(() => {
    const onOpen = (event: CustomEvent<OpenAgentAuthorizationBannerEventDetail>) => {
      const {slug, displayName, avatarUrl, authorizationStatus} = event.detail

      // Status precedence: 5-part token > mockAgentAuthState fallback.
      const apiRequiresAuth = needsAuthorizationFromTokenStatus(authorizationStatus)
      const requiresAuthentication =
        apiRequiresAuth ?? mockAgentAuthState(slug, displayName, avatarUrl).requiresAuthentication

      if (requiresAuthentication) {
        setAgent({slug, displayName, avatarUrl})
      } else {
        setAgent(null)
      }
    }
    const onClose = () => setAgent(null)

    window.addEventListener(OPEN_EVENT, onOpen)
    window.addEventListener(CLOSE_EVENT, onClose)
    return () => {
      window.removeEventListener(OPEN_EVENT, onOpen)
      window.removeEventListener(CLOSE_EVENT, onClose)
    }
  }, [])

  const handleAuthenticate = useCallback(async () => {
    if (!agent) return
    try {
      const integrationId = agentAuthStatuses.get(agent.slug)?.integrationId
      const url = await requestAuthorizationUrl({slug: agent.slug, integrationId}, {nwo})
      window.location.assign(url)
    } catch (error) {
      // eslint-disable-next-line no-console
      console.error('[agent-authorization] failed to fetch authorization URL', error)
    }
  }, [agent, agentAuthStatuses, nwo])

  if (!agent) return null

  return (
    <div className={styles.wrapper}>
      <AgentAuthorizationBanner agent={agent} onAuthenticate={handleAuthenticate} />
    </div>
  )
}

export const AGENT_AUTHORIZATION_BANNER_OPEN_EVENT = OPEN_EVENT
export const AGENT_AUTHORIZATION_BANNER_CLOSE_EVENT = CLOSE_EVENT
