import {Banner} from '@primer/react'

import type {AgentAuthorizationAgent} from './types'

export type AgentAuthorizationBannerProps = {
  agent: AgentAuthorizationAgent
  /** Called when the user clicks "Authenticate". The host is responsible
   *  for navigating to the OAuth start URL or opening the dialog. */
  onAuthenticate: () => void
}

/**
 * Inline banner shown under a comment composer when an unresolved `@agent[agent]`
 * mention belongs to an agent the viewer hasn't authorized.
 */
export function AgentAuthorizationBanner({agent, onAuthenticate}: AgentAuthorizationBannerProps) {
  return (
    <Banner
      variant="warning"
      title="Authorization required"
      hideTitle
      description={`${agent.displayName} requires authorization first.`}
      primaryAction={<Banner.PrimaryAction onClick={onAuthenticate}>Authenticate</Banner.PrimaryAction>}
    />
  )
}
